-- Q2: Matches played in the last 30 days
SELECT m.match_description, t1.team_name AS team1, t2.team_name AS team2, v.venue_name || ', ' || v.city AS venue, m.match_date FROM matches m JOIN teams t1 ON m.team1_id = t1.team_id JOIN teams t2 ON m.team2_id = t2.team_id JOIN venues v ON m.venue_id = v.venue_id ORDER BY m.match_date DESC;